// Initial setup
const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');
const WIDTH = canvas.width = 400;
const HEIGHT = canvas.height = 400;
const GRavity = 9.8; // m/s^2
const initialAngle = 45; // degrees
const pendulumLength = 100; // meters
let angle = initialAngle * (Math.PI / 180);
let velocity = 0;
let time = 0;
let isReleased = false;

// Draw the pendulum
function drawPendulum() {
  ctx.clearRect(0, 0, WIDTH, HEIGHT);
  ctx.beginPath();
  ctx.arc(WIDTH / 2, HEIGHT / 2, pendulumLength, 0, 2 * Math.PI);
  ctx.fillStyle = 'gray';
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(WIDTH / 2, HEIGHT / 2);
  ctx.lineTo(WIDTH / 2 + pendulumLength * Math.sin(angle), HEIGHT / 2 - pendulumLength * Math.cos(angle));
  ctx.stroke();
}

// Update the pendulum
function updatePendulum() {
  if (isReleased) {
    angle += velocity;
    velocity -= GRavity / pendulumLength * Math.sin(angle);
    time += 0.01;
  }
}

// Check if the pendulum has stopped
function hasStopped() {
  return Math.abs(velocity) < 0.01;
}

// Event listeners
canvas.addEventListener('mousedown', () => {
  isReleased = true;
});

canvas.addEventListener('mouseup', () => {
  isReleased = false;
});

// Main loop
function loop() {
  updatePendulum();
  drawPendulum();
  if (hasStopped()) {
    angle = initialAngle * (Math.PI / 180);
    velocity = 0;
  }
  requestAnimationFrame(loop);
}

loop();

// Input box for initial angle
const input = document.getElementById('initial-angle');
const button = document.getElementById('release');

button.addEventListener('click', () => {
  initialAngle = parseInt(input.value);
  angle = initialAngle * (Math.PI / 180);
  velocity = 0;
  isReleased = false;
});

drawPendulum();
